package com.termux.app.voicepatrol;

import static org.junit.Assert.*;
import com.termux.app.voicepatrol.VoicePatrolTestDoubles.*;
import java.util.*;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;

@RunWith(RobolectricTestRunner.class)
public class VoicePatrolControllerTest {
 static final String SESSION_DEFINITION="https://pc.example:8443/owner/session.json?k=secret";
 static final String DERIVED_ENDPOINT="https://pc.example:8443/api/live/sessions?k=secret";
 static final class H { final Calls calls=new Calls(); final Speech speech=new Speech(); final Actions actions=new Actions(); final Connections factory=new Connections(); final Log log=new Log(); final VoicePatrolController controller=new VoicePatrolController(DERIVED_ENDPOINT,calls,speech,actions,factory,log); Connection connection(){return factory.opened.get(factory.opened.size()-1);} }
 static VoicePatrolCall call(String name,String body){return new VoicePatrolCall(name,body);}
 static H initial(String name,String body){H h=new H();h.calls.calls=new ArrayList<>(Arrays.asList(call(name,body)));h.controller.start();return h;}
 static void open(H h){h.speech.spoken();assertEquals(DERIVED_ENDPOINT,h.connection().endpoint);}
 static void startBackend(H h){open(h);h.connection().listener.onEventReceived(VoicePatrolTestDoubles.event("session.started"));}
 static void assertFailure(H h,String reason,String phrase){open(h);h.connection().listener.onConnectFailed(reason);assertEquals(VoicePatrolPhase.WAITING_FOR_CALL,h.controller.getPhase());assertEquals(1,h.log.warnings.size());assertEquals("音声の接続を始められませんでした。"+phrase,h.speech.texts.get(1));h.controller.onCallingSessionsChanged();assertEquals(1,h.factory.opened.size());}
 @Test public void readsBodyVerbatimBeforeOpeningAndShowsSession() throws Exception {H h=initial("alpha","body verbatim");assertEquals(VoicePatrolPhase.READING_CALL,h.controller.getPhase());assertEquals(Arrays.asList("body verbatim"),h.speech.texts);assertEquals(Arrays.asList("alpha"),h.actions.shown);assertTrue(h.factory.opened.isEmpty());open(h);assertEquals(VoicePatrolPhase.CONNECTING,h.controller.getPhase());}
 @Test public void opensWithDerivedEndpointAndSendsNameAndBodyThinkingPayloads() throws Exception {H h=initial("alpha","body verbatim");startBackend(h);assertFalse(h.connection().events.isEmpty());String joined=""; for(String raw:h.connection().events){JSONObject j=new JSONObject(raw);assertEquals("session.thinking.append",j.getString("type"));assertTrue(j.isNull("delegation_id"));assertFalse(raw.contains("session.commentary.append"));joined+=j.getString("content");}assertTrue(joined.contains("alpha"));assertTrue(joined.contains("body verbatim"));}
 @Test public void microphoneIsDisabledDuringRepeatSpeechAndEnabledAfterCompletion() throws Exception {H h=initial("alpha","body");startBackend(h);h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("repeat-id","owner_call_repeat","{}"));assertEquals(Arrays.asList(true,false),h.connection().microphones);h.speech.spoken();assertEquals(Arrays.asList(true,false,true),h.connection().microphones);}
 @Test public void replyOutputPrecedesResponseCreateWithSameCallIdAndMovesNext() throws Exception {H h=initial("alpha","first");h.calls.calls=new ArrayList<>(Arrays.asList(call("alpha","first"),call("beta","second")));startBackend(h);h.connection().events.clear();h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("reply-id","session_reply_send","{\"replyText\":\"yes\"}"));assertEquals(Arrays.asList("alpha|yes"),h.actions.replies);assertEquals(2,h.connection().events.size());JSONObject output=new JSONObject(h.connection().events.get(0));assertEquals("response.item.create",output.getString("type"));assertEquals("reply-id",output.getJSONObject("item").getString("call_id"));assertEquals("response.create",new JSONObject(h.connection().events.get(1)).getString("type"));assertEquals("second",h.speech.texts.get(1));}
 @Test public void deliveredReplyReportsSentAndMovesToNextCall() throws Exception {H h=initial("alpha","first");h.calls.calls=new ArrayList<>(Arrays.asList(call("alpha","first"),call("beta","second")));startBackend(h);h.connection().events.clear();h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("reply-id","session_reply_send","{\"replyText\":\"yes\"}"));assertEquals("sent",new JSONObject(new JSONObject(h.connection().events.get(0)).getJSONObject("item").getString("output")).getString("status"));assertEquals("second",h.speech.texts.get(1));}
 @Test public void undeliveredReplyReportsErrorSpeaksJapaneseAndRemainsEligible() throws Exception {H h=initial("alpha","first");startBackend(h);h.actions.replyDelivered=false;h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("reply-id","session_reply_send","{\"replyText\":\"yes\"}"));assertEquals("reply_not_delivered",new JSONObject(h.connection().events.get(h.connection().events.size()-2)).getJSONObject("item").getString("output").replace("{\"error\":\"reply_not_delivered\"}","reply_not_delivered"));assertEquals("返信を送れませんでした。",h.speech.texts.get(1));assertEquals(VoicePatrolPhase.CONVERSING,h.controller.getPhase());h.actions.replyDelivered=true;h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("reply-id-2","session_reply_send","{\"replyText\":\"again\"}"));assertTrue(h.actions.replies.contains("alpha|again"));}
 @Test public void sessionSkipMovesNextWithoutReplyAndKeepsCallId() throws Exception {H h=initial("alpha","first");h.calls.calls=new ArrayList<>(Arrays.asList(call("alpha","first"),call("beta","second")));startBackend(h);h.connection().events.clear();h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("skip-id","session_skip","{}"));assertTrue(h.actions.replies.isEmpty());assertEquals("skip-id",new JSONObject(h.connection().events.get(0)).getJSONObject("item").getString("call_id"));assertEquals("response.create",new JSONObject(h.connection().events.get(1)).getString("type"));assertEquals("second",h.speech.texts.get(1));}
 @Test public void ownerCallRepeatReadsCurrentBodyWithoutContext() throws Exception {H h=initial("alpha","repeat body");startBackend(h);int eventCount=h.connection().events.size();h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("repeat-id","owner_call_repeat","{}"));assertEquals("repeat body",h.speech.texts.get(1));for(String raw:h.connection().events.subList(eventCount,h.connection().events.size())){assertFalse(raw.contains("session.thinking.append"));}}
 @Test public void missingReplyTextReturnsExactErrorAndContinues() throws Exception {H h=initial("alpha","body");startBackend(h);h.connection().events.clear();h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("missing-id","session_reply_send","{}"));assertTrue(h.actions.replies.isEmpty());assertEquals("missing-id",new JSONObject(h.connection().events.get(0)).getJSONObject("item").getString("call_id"));assertTrue(new JSONObject(h.connection().events.get(0)).getJSONObject("item").getString("output").contains("error"));assertEquals("response.create",new JSONObject(h.connection().events.get(1)).getString("type"));}
 @Test public void nonStringReplyTextReturnsExactErrorAndContinues() throws Exception {H h=initial("alpha","body");startBackend(h);h.connection().events.clear();h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("number-id","session_reply_send","{\"replyText\":3}"));assertTrue(h.actions.replies.isEmpty());assertTrue(new JSONObject(h.connection().events.get(0)).getJSONObject("item").getString("output").contains("error"));assertEquals("response.create",new JSONObject(h.connection().events.get(1)).getString("type"));}
 @Test public void emptyReplyTextReturnsExactErrorAndContinues() throws Exception {H h=initial("alpha","body");startBackend(h);h.connection().events.clear();h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("empty-id","session_reply_send","{\"replyText\":\"\"}"));assertTrue(h.actions.replies.isEmpty());assertTrue(new JSONObject(h.connection().events.get(0)).getJSONObject("item").getString("output").contains("error"));assertEquals("response.create",new JSONObject(h.connection().events.get(1)).getString("type"));}
 @Test public void unknownToolReturnsExactErrorAndLogs() throws Exception {H h=initial("alpha","body");startBackend(h);h.connection().events.clear();h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("unknown-id","unknown_tool","{}"));JSONObject error=new JSONObject(h.connection().events.get(0));assertEquals("unknown-id",error.getJSONObject("item").getString("call_id"));assertTrue(error.getJSONObject("item").getString("output").contains("error"));assertEquals(1,h.log.warnings.size());assertTrue(h.log.warnings.get(0).contains("unknown_tool"));}
 @Test public void noCallSendsCloseWaitsAndClosesOnlyAfterClosed() throws Exception {H h=initial("alpha","body");startBackend(h);h.calls.calls.clear();h.connection().events.clear();h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("skip-id","session_skip","{}"));assertEquals(VoicePatrolPhase.WAITING_FOR_CALL,h.controller.getPhase());assertEquals("session.close",new JSONObject(h.connection().events.get(2)).getString("type"));assertEquals(0,h.connection().closes);h.connection().listener.onEventReceived(VoicePatrolTestDoubles.event("session.closed"));assertEquals(1,h.connection().closes);}
 @Test public void newCallAfterCloseReopensFromReading() throws Exception {H h=initial("alpha","body");startBackend(h);h.calls.calls.clear();h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("skip-id","session_skip","{}"));h.connection().listener.onEventReceived(VoicePatrolTestDoubles.event("session.closed"));h.calls.calls.add(call("beta","new body"));h.controller.onCallingSessionsChanged();assertEquals(VoicePatrolPhase.READING_CALL,h.controller.getPhase());assertEquals("new body",h.speech.texts.get(1));assertEquals("beta",h.actions.shown.get(1));}
 @Test public void apiKeyFailureSpeaksAndDoesNotRetry() throws Exception {assertFailure(initial("a","b"),"openai_api_key_missing","OpenAI の API キーが設定されていません");}
 @Test public void liveSessionFailureSpeaksAndDoesNotRetry() throws Exception {assertFailure(initial("a","b"),"openai_live_session_failed","OpenAI との音声セッションを開始できませんでした");}
 @Test public void badRequestFailureSpeaksAndDoesNotRetry() throws Exception {assertFailure(initial("a","b"),"HTTP 400","サーバーがリクエストを受け付けませんでした");}
 @Test public void tokenRejectionFailureSpeaksAndDoesNotRetry() throws Exception {assertFailure(initial("a","b"),"token_rejected","原因不明のエラーが起きました");}
 @Test public void serviceUnavailableFailureSpeaksJapanesePhrase() throws Exception {assertFailure(initial("a","b"),"HTTP 503","サーバーでエラーが起きました");}
 @Test public void speechFailureSpeaksJapanesePhraseAndWaits() throws Exception {H h=initial("alpha","body");startBackend(h);h.connection().listener.onEventReceived(VoicePatrolTestDoubles.function("repeat-id","owner_call_repeat","{}"));h.speech.failed("tts_interrupted");assertEquals("読み上げに失敗しました。読み上げが途中で止まりました",h.speech.texts.get(2));assertEquals(VoicePatrolPhase.WAITING_FOR_CALL,h.controller.getPhase());assertEquals(1,h.log.warnings.size());assertTrue(h.log.warnings.get(0).contains("tts_interrupted"));}
 @Test public void disconnectionAfterStartSpeaksAndWaitsAndCloses() throws Exception {H h=initial("alpha","body");startBackend(h);h.connection().listener.onDisconnected("network_error");assertEquals("音声の接続が切れました。",h.speech.texts.get(1));assertEquals(VoicePatrolPhase.WAITING_FOR_CALL,h.controller.getPhase());assertEquals(1,h.connection().closes);h.connection().listener.onDisconnected("again");assertEquals(2,h.speech.texts.size());}
 @Test public void serverSessionClosedWhileConversingSpeaksAndWaits() throws Exception {H h=initial("alpha","body");startBackend(h);h.connection().listener.onEventReceived(VoicePatrolTestDoubles.event("session.closed"));assertEquals("音声の接続が切れました。",h.speech.texts.get(1));assertEquals(VoicePatrolPhase.WAITING_FOR_CALL,h.controller.getPhase());}
}
